<?php

namespace App\Permissions;

use Illuminate\Support\Str;

/** Renders resources/js/lib/permissions.ts from the PHP enums (the single source of truth). */
final class PermissionTypeScriptExporter
{
    public const PATH = 'resources/js/lib/permissions.ts';

    public static function render(): string
    {
        $lines = [
            '// Generated by `php artisan permissions:export`. Do not edit by hand.',
            '',
            'export const Permission = {',
        ];

        foreach (PermissionRegistry::GROUPS as $group) {
            $lines[] = '    '.Str::beforeLast(class_basename($group), 'Permission').': {';

            foreach ($group::cases() as $case) {
                $lines[] = "        {$case->name}: '{$case->value}',";
            }

            $lines[] = '    },';
        }

        $lines[] = '} as const;';
        $lines[] = '';
        $lines[] = 'type Groups = typeof Permission;';
        $lines[] = '';
        $lines[] = 'export type Permission = {';
        $lines[] = '    [G in keyof Groups]: Groups[G][keyof Groups[G]];';
        $lines[] = '}[keyof Groups];';

        return implode("\n", $lines)."\n";
    }
}
